SELECT id, order_id, product_id, SUM(unit_price) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_unit_price, AVG(quantity) OVER (ORDER BY unit_price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) quantity_avg_3, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_quantity, STDDEV_SAMP(unit_price) OVER (PARTITION BY product_id) product_id_stddev_samp_unit_price FROM order_items
